/*
 * ------------------------------------------------------------------------
 * 名称：child.c
 * 说明：测试用的子程序：往扩展 RAM 的固定单元写一个标记就返回，用来检查 sb_exec。
 * 作者：sungbin
 * 邮箱：sungbin@3578.cn
 * 日期：2026-11-11
 * 备注：由 file.c 经 sb_exec 运行；标记单元 $7F00 在 $6000-$7FFF 的扩展 RAM 里，任何窗口映射下都可见。
 * ------------------------------------------------------------------------
 */
int main(void)
{
    *(volatile unsigned char *)0x7F00 = 0xA5;
    return 0;
}
